// === Tab: breathingBalls2 ===

let balls;
let firstBall;
let timer;
let totalBalls = 0;
let ballcolor;

function setup() {
  createCanvas(600, 600);
  colorMode(HSB,360,100,100,100);
  ballcolor = color(int(random(100,150)),100,100,25);
  balls = new Array(200);
  firstBall = new Bball(random(50, 150), 75+random(width -150), 150 + height, ballcolor);
  timer = new Timer(500);
  timer.start();

  frameRate(25);
}

function draw() {

  background(noise(ballcolor+80), 70, 100,25);

    firstBall.display();
    firstBall.fall();

  if (timer.isFinished()&&totalBalls < balls.length) {
    ballcolor = color(int(random(150,300)),100,100,25);
    balls[totalBalls] = new Bball(random(50, 150), 75+random(width -150), height + 150, ballcolor);
    //ballcolor = color(0, random(240, 255), random(200));
    totalBalls ++;
    if (totalBalls == balls.length) {
      println("end");
    }
    timer.start();
  }
  for (i = 0; i < totalBalls; i++) {
    balls[i].display();
    balls[i].fall();
  }

  //let 1200 frames for movie
 /* if(frameCount <= 1200){
    saveFrame("breathingBall2-####.tif");
  }

  if (frameCount == 600) {
    saveFrame("breathingBalls.jpg");

  }*/

}
class Bball {
  ballWidth;
  ballHeight;
  x, y, w;
  theta;
  c;
  g;

  constructor(tempBW, tempX, tempY, tempC) {
    w = tempBW;
    x = tempX;
    y = tempY;
    theta = random(1);
    g = random(1,3);
    c = tempC;
  }



  function display() {
    noStroke();
    theta = noise(-1,1)+theta;
    ballWidth = w +((sin(theta)) * 20);
    ballHeight = w + ((cos(theta)) * 30);

      fill(c);

    ellipse(x, y, ballWidth, ballHeight);
    theta += 0.05;

  }

  function fall(){
    y = y + g;
    if(y <= ballHeight/2){
     y = ballHeight/2;
     g = g * -1;
    }
    if(y >= height - ballHeight/2){
      y = height - ballHeight/2;
      g = g * -1;
    }
  }
}
class Timer {

  savedTime; // let Timer started
  totalTime; // let long let should last

  constructor(tempTotalTime) {
    totalTime = tempTotalTime;
  }

  // let the timer
  function start() {
    // let the timer starts it stores the current time in milliseconds.
    savedTime = millis();
  }

  // let function isFinished() returns true if 5,000 ms have passed. 
  // let work of the timer is farmed out to this method.
  isFinished() { 
    // let how much time has passed
    let passedTime = millis()- savedTime;
    if (passedTime > totalTime) {
      return true;
    } else {
      return false;
    }
  }
}

